/// Fractional index keys (spec §3): a Swift port of David Greenspan's scheme as published in the
/// `fractional-indexing` npm package (v3.2.0, base 62). Keys sort byte-wise, and `keyBetween(a, b)`
/// returns a key strictly between `a` and `b`, with `nil` meaning an open end.
///
/// Tested against vectors generated by the npm package (Tests/…/fractional-index-vectors.json).
public enum FractionalIndex {
    public enum Failure: Error, Equatable {
        case invalidKey(String)
        case notOrdered(String, String)
        case exhausted
    }

    public static func keyBetween(_ a: String?, _ b: String?) throws(Failure) -> String {
        let r = try between(a.map { Array($0.utf8) }, b.map { Array($0.utf8) })
        return String(decoding: r, as: UTF8.self)
    }

    /// `n` evenly spread keys strictly between `a` and `b`, in ascending order.
    public static func keysBetween(_ a: String?, _ b: String?, count n: Int) throws(Failure) -> [String] {
        try nBetween(a.map { Array($0.utf8) }, b.map { Array($0.utf8) }, n).map { String(decoding: $0, as: UTF8.self) }
    }

    public static func isValidKey(_ key: String) -> Bool {
        do { try validate(Array(key.utf8)); return true } catch { return false }
    }

    // MARK: - Port

    private typealias Key = [UInt8]
    private static let zero = UInt8(ascii: "0")
    private static let digits = Array("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".utf8)
    private static let smallestInteger: Key = [UInt8(ascii: "A")] + Array(repeating: zero, count: 26)

    private static func value(_ c: UInt8) -> Int? {
        switch c {
        case UInt8(ascii: "0")...UInt8(ascii: "9"): Int(c - UInt8(ascii: "0"))
        case UInt8(ascii: "A")...UInt8(ascii: "Z"): Int(c - UInt8(ascii: "A")) + 10
        case UInt8(ascii: "a")...UInt8(ascii: "z"): Int(c - UInt8(ascii: "a")) + 36
        default: nil
        }
    }

    private static func less(_ a: Key, _ b: Key) -> Bool { a.lexicographicallyPrecedes(b) }

    private static func midpoint(_ a: Key, _ b: Key?) throws(Failure) -> Key {
        if let b, !less(a, b) { throw .notOrdered(string(a), string(b)) }
        if a.last == zero || b?.last == zero { throw .invalidKey(string(b ?? a)) }
        if let b {
            // Remove the longest common prefix, padding `a` with zeros as we go.
            var n = 0
            while n < b.count, (n < a.count ? a[n] : zero) == b[n] { n += 1 }
            if n > 0 {
                return Array(b[..<n]) + (try midpoint(Array(a.dropFirst(n)), Array(b.dropFirst(n))))
            }
        }
        // The first digits (or lack of digit) differ.
        guard let digitA = a.isEmpty ? 0 : value(a[0]) else { throw .invalidKey(string(a)) }
        guard let digitB = b.map({ value($0[0]) }) ?? digits.count else { throw .invalidKey(string(b!)) }
        if digitB - digitA > 1 {
            return [digits[(digitA + digitB + 1) / 2]] // Math.round(0.5 * (a + b))
        }
        // The first digits are consecutive.
        if let b, b.count > 1 { return [b[0]] }
        return [digits[digitA]] + (try midpoint(Array(a.dropFirst()), nil))
    }

    private static func integerLength(_ head: UInt8) throws(Failure) -> Int {
        switch head {
        case UInt8(ascii: "a")...UInt8(ascii: "z"): Int(head - UInt8(ascii: "a")) + 2
        case UInt8(ascii: "A")...UInt8(ascii: "Z"): Int(UInt8(ascii: "Z") - head) + 2
        default: throw .invalidKey(string([head]))
        }
    }

    private static func integerPart(_ key: Key) throws(Failure) -> Key {
        guard let head = key.first else { throw .invalidKey("") }
        let n = try integerLength(head)
        guard n <= key.count else { throw .invalidKey(string(key)) }
        return Array(key[..<n])
    }

    private static func validate(_ key: Key) throws(Failure) {
        guard key != smallestInteger, key.allSatisfy({ value($0) != nil }) else { throw .invalidKey(string(key)) }
        let i = try integerPart(key)
        if key.count > i.count, key.last == zero { throw .invalidKey(string(key)) }
    }

    private static func increment(_ x: Key) throws(Failure) -> Key? {
        guard x.count == (try integerLength(x[0])) else { throw .invalidKey(string(x)) }
        let head = x[0]
        var digs = Array(x.dropFirst())
        var carry = true
        var i = digs.count - 1
        while carry, i >= 0 {
            let d = value(digs[i])! + 1
            if d == digits.count { digs[i] = zero } else { digs[i] = digits[d]; carry = false }
            i -= 1
        }
        if carry {
            if head == UInt8(ascii: "Z") { return [UInt8(ascii: "a"), zero] }
            if head == UInt8(ascii: "z") { return nil }
            let h = head + 1
            if h > UInt8(ascii: "a") { digs.append(zero) } else { digs.removeLast() }
            return [h] + digs
        }
        return [head] + digs
    }

    private static func decrement(_ x: Key) throws(Failure) -> Key? {
        guard x.count == (try integerLength(x[0])) else { throw .invalidKey(string(x)) }
        let head = x[0]
        var digs = Array(x.dropFirst())
        var borrow = true
        var i = digs.count - 1
        while borrow, i >= 0 {
            let d = value(digs[i])! - 1
            if d == -1 { digs[i] = digits[digits.count - 1] } else { digs[i] = digits[d]; borrow = false }
            i -= 1
        }
        if borrow {
            if head == UInt8(ascii: "a") { return [UInt8(ascii: "Z"), digits[digits.count - 1]] }
            if head == UInt8(ascii: "A") { return nil }
            let h = head - 1
            if h < UInt8(ascii: "Z") { digs.append(digits[digits.count - 1]) } else { digs.removeLast() }
            return [h] + digs
        }
        return [head] + digs
    }

    private static func between(_ a: Key?, _ b: Key?) throws(Failure) -> Key {
        if let a { try validate(a) }
        if let b { try validate(b) }
        if let a, let b, !less(a, b) { throw .notOrdered(string(a), string(b)) }
        guard let a else {
            guard let b else { return [UInt8(ascii: "a"), zero] }
            let ib = try integerPart(b)
            let fb = Array(b[ib.count...])
            if ib == smallestInteger { return ib + (try midpoint([], fb)) }
            if less(ib, b) { return ib }
            guard let res = try decrement(ib) else { throw .exhausted }
            return res
        }
        guard let b else {
            let ia = try integerPart(a)
            let fa = Array(a[ia.count...])
            guard let i = try increment(ia) else { return ia + (try midpoint(fa, nil)) }
            return i
        }
        let ia = try integerPart(a)
        let fa = Array(a[ia.count...])
        let ib = try integerPart(b)
        let fb = Array(b[ib.count...])
        if ia == ib { return ia + (try midpoint(fa, fb)) }
        guard let i = try increment(ia) else { throw .exhausted }
        if less(i, b) { return i }
        return ia + (try midpoint(fa, nil))
    }

    private static func nBetween(_ a: Key?, _ b: Key?, _ n: Int) throws(Failure) -> [Key] {
        if n <= 0 { return [] }
        if n == 1 { return [try between(a, b)] }
        if b == nil {
            var c = try between(a, b)
            var result = [c]
            for _ in 0..<(n - 1) {
                c = try between(c, b)
                result.append(c)
            }
            return result
        }
        if a == nil {
            var c = try between(a, b)
            var result = [c]
            for _ in 0..<(n - 1) {
                c = try between(a, c)
                result.append(c)
            }
            return result.reversed()
        }
        let mid = n / 2
        let c = try between(a, b)
        return try nBetween(a, c, mid) + [c] + nBetween(c, b, n - mid - 1)
    }

    private static func string(_ k: Key) -> String { String(decoding: k, as: UTF8.self) }
}
